exec(open(__file__.replace("n1.py","lib.py")).read())
KCH = C.KCH; klic = C.klic; glic = C.glic; G1 = C.G1; AFD1 = C.AFD1
NA = (False,"licensure_delegator_not_authority"); NR = (False,"authority_not_reached")
duty = lambda S: sorted(ST.Seats(S).holders("duty","g"))
# body growth: lone holder A confers `moderate` on C (lone conferral, C's acceptance by cosigning)
DC = ST.offer("dc","A","C","moderate","g","self",("g",))
DCA = ST.accept("dca","C","dc")
run("N0 control: after dc, holders", [G1,DC,DCA,A("e","RD","g"),glic("l","g","Q")], "RD","l", extra=duty)
run("N1 holders A,C; A alone edge for g naming dca (control)", [G1,DC,DCA,A("e","RD","g",depth=1),A("f","A","K",on_behalf="g",names=("dca",)),klic("l")], "RD","l",KCH, want=NR)
run("N1b holders A,C; A alone edge for g naming only g (old past: A lone)", [G1,DC,DCA,A("e","RD","g",depth=1),A("f","A","K",on_behalf="g",names=("g",)),klic("l")], "RD","l",KCH, want=NR)
LS = ST.offer("ls","A","X","license","g","self",("g",)); LSA = ST.accept("lsa","X","ls")
run("N2 holders A,C; A alone confers license on X naming only g; X licenses", [G1,DC,DCA,LS,LSA,A("e","RD","g"),glic("l","g","X")|{"names":("lsa","dca")}], "RD","l", want=NA)
LS2 = ST.offer("ls","A","X","license","g","self",("dca",))
run("N2c control: same seat naming dca", [G1,DC,DCA,LS2,LSA,A("e","RD","g"),glic("l","g","X")|{"names":("lsa",)}], "RD","l", want=NA)
DC2 = ST.offer("dc2","A","D","moderate","g","self",("g",)); DC2A = ST.accept("dc2a","D","dc2")
run("N3 holders A,C; A alone confers moderate on D naming only g", [G1,DC,DCA,DC2,DC2A,A("e","RD","g"),glic("l","g","Q")], "RD","l", extra=duty)
# affiliation: lone officer A appoints B,C officers (counted, A alone is the body), then A alone backdates
APB = ST.offer("apb","A",("B","C"),"member","af","group",("af",),head=("af",),counted=ST.OFFICER,role=ST.OFFICER,policy=None)
off = lambda S: sorted(ST.Seats(S).holders(ST.OFFICER,"af"))
run("N4 AFD1 + A appoints B,C officers", [AFD1,APB,A("e","RD","af"),glic("l","af","Q")], "RD","l", extra=off)
LSO = ST.offer("lso","A","X","license","af","self",("af",)); LSOA = ST.accept("lsoa","X","lso")
run("N4b officers A,B,C; A alone confers license on X naming only af", [AFD1,APB,LSO,LSOA,A("e","RD","af"),glic("l","af","X")|{"names":("lsoa","apb")}], "RD","l", want=NA, extra=off)
run("N4c A alone licence for af naming only af (lone officer then)", [AFD1,APB,A("e","RD","af"),glic("l","af","A")|{"names":("af",)}], "RD","l", want=NA, extra=off)
run("N4d A alone licence for af naming apb (control)", [AFD1,APB,A("e","RD","af"),glic("l","af","A")|{"names":("apb",)}], "RD","l", want=NA, extra=off)
